	@Test
	void aLargeSingleAliasGroupCanBeReadLazilyWithoutMaterializingTheGroup() {
		TrackingFactory factory = new TrackingFactory();
		try (LegacySemanticIndex<String, Long> index = new LegacySemanticIndex<>(() -> factory)) {
			for (long id = 0; id < 4096; id++) {
				index.add("same semantic value", id);
			}
			assertThat(factory.initialized).isTrue();
			Iterator<Long> aliases = index.aliases("same semantic value");
			assertThat(aliases.hasNext()).isTrue();
			long first = aliases.next();
			assertThat(first).isBetween(0L, 4095L);
			index.remove(first);
			assertThat(aliases).toIterable().hasSize(4095);
		}
		assertThat(factory.closed).isTrue();
	}

